/// Android media through the Java generated by dartvel build. No channels.
library;

import 'dart:async';
import 'dart:ui' show PlatformDispatcher;

import 'package:dartvel_core/dartvel.dart';
import 'package:jni/jni.dart';

import '../../media/media_box.dart';
import '../../media/native_backend.dart';
import '../../media/native_events.dart';

/// Signatures are checked by the smoke APK's Java compilation and JNI at
/// lookup. All temporary string references are released on every call.
final class _Bridge implements DVNativeMediaBridge {
  _Bridge(String name) : type = JClass.forName(name);
  final JClass type;
  final _methods = <String, JStaticMethodId>{};
  static const signatures = <String, String>{
    'create': '(JZ)J',
    'open': '(JLjava/lang/String;)V',
    'play': '(J)V',
    'pause': '(J)V',
    'seek': '(JJJ)V',
    'setVolume': '(JD)V',
    'textureId': '(J)J',
    'poll': '(J)Ljava/lang/String;',
    'dispose': '(J)V',
    'backgroundDeclared': '()Z',
    'capabilities': '()Ljava/lang/String;',
    'devices': '()Ljava/lang/String;',
    'createCamera': '(J)J',
    'cameraTextureId': '(J)J',
    'openCamera': '(JLjava/lang/String;Ljava/lang/String;)V',
    'closeCamera': '(J)V',
    'takePhoto': '(JLjava/lang/String;Ljava/lang/String;)V',
    'startRecording': '(JLjava/lang/String;Ljava/lang/String;Z)V',
    'stopRecording': '(J)V',
    'setTorch': '(JZ)V',
    'pollCamera': '(J)Ljava/lang/String;',
    'disposeCamera': '(J)V',
    'publish': '(Ljava/lang/String;Ljava/lang/String;Ljava/lang/String;Ljava/lang/String;ZJJ)V',
    'clear': '()V',
    'commands': '()Ljava/lang/String;',
    'request': '()Z',
    'abandon': '()V',
    'losses': '()J',
  };
  @override
  Object? call(String method, List<Object?> arguments) {
    final signature = signatures[method]!;
    final id = _methods.putIfAbsent(
      method,
      () => type.staticMethodId(method, signature),
    );
    final strings = <JString>[];
    final args = <dynamic>[
      for (final arg in arguments)
        if (arg is String) (strings..add(arg.toJString())).last else arg,
    ];
    try {
      switch (signature.substring(signature.indexOf(')') + 1)) {
        case 'J':
          return id.call(type, jlong.type, args);
        case 'Z':
          return id.call(type, jboolean.type, args);
        case 'V':
          id.call(type, jvoid.type, args);
          return null;
        default:
          return id
              .callNullable(type, JString.type, args)
              ?.toDartString(releaseOriginal: true);
      }
    } finally {
      for (final string in strings) {
        string.release();
      }
    }
  }
}

abstract final class DVAndroidMedia {
  static bool _registered = false;
  static String? lastPlayerFailure;
  static String? lastCameraFailure;
  static void register({required String directory}) {
    if (_registered) return;
    _registered = true;
    final engineId = PlatformDispatcher.instance.engineId;
    if (engineId == null) {
      lastPlayerFailure = lastCameraFailure = 'Flutter supplied no engine id';
      return;
    }
    try {
      final player = _Bridge(dvAndroidMediaPlayerClass);
      final background = player.call('backgroundDeclared', []) == true;
      final focus = _Bridge(dvAndroidAudioFocusClass);
      final session = _Bridge(dvAndroidMediaSessionClass);
      DVMediaBackends.registerPlayer(
        (source, kind) => DVNativePlayerBackend(
          player,
          engineId: engineId,
          video: kind == .video,
          capabilities: DVMediaBackendCapabilities(backgroundAudio: background),
        ),
        backgroundAudioDeclared: background,
      );
      DVMediaBackends.registerAudioFocus(_Focus(focus));
      DVMediaBackends.registerNowPlaying(_Session(session));
    } on Object catch (error) {
      lastPlayerFailure = 'No generated Android player: $error';
    }
    try {
      final camera = _Bridge(dvAndroidCameraClass);
      final capabilities = dvParseCameraCapabilities(
        camera.call('capabilities', []) as String?,
      );
      DVMediaBackends.registerCamera(
        () => DVNativeCameraBackend(
          camera,
          engineId: engineId,
          capabilities: capabilities,
        ),
        capabilities: capabilities,
        directory: directory,
      );
    } on Object catch (error) {
      lastCameraFailure = 'No generated Android camera: $error';
    }
  }
}

final class _Focus implements DVAudioFocusBackend {
  _Focus(this.bridge);
  final _Bridge bridge;
  @override
  Future<bool> request() async => bridge.call('request', []) == true;
  @override
  Future<void> abandon() async {
    bridge.call('abandon', []);
  }

  @override
  Stream<void> get losses => Stream<int>.periodic(
    const Duration(milliseconds: 100),
    (_) => bridge.call('losses', []) as int,
  ).where((n) => n > 0).map((_) {});
}

final class _Session implements DVNowPlayingBackend {
  _Session(this.bridge);
  final _Bridge bridge;
  @override
  Future<void> publish(DVMediaSession session, DVNowPlayingState state) async {
    bridge.call('publish', [
      session.title,
      session.artist,
      session.album,
      session.artworkUrl,
      state.playing,
      state.position.inMilliseconds,
      state.duration.inMilliseconds,
    ]);
  }

  @override
  Future<void> clear() async {
    bridge.call('clear', []);
  }

  @override
  Stream<DVMediaCommand> get commands => Stream<String?>.periodic(
    const Duration(milliseconds: 100),
    (_) => bridge.call('commands', []) as String?,
  ).expand(dvParseMediaCommands);
}
